# Phase 12: Store.category — 9 hardcoded choices -> FK to the catalog tree.
#
# Hand-ordered like users/0006 (Phase 11): the autogenerated AlterField drops
# the choice column before its values are mapped anywhere. The safe order is
# rename -> add the FK -> map the data -> drop the renamed column.
#
# The mapping needs rows to map *onto*: on databases that predate
# `load_categories` this migration creates the nine legacy roots itself
# (leaf-shaped mptt fields, one fresh tree each). `manage.py load_categories`
# later upserts the curated launch tree by slug and calls `rebuild()`, which
# self-heals any tree fields set here.

import django.db.models.deletion
from django.db import migrations, models
from django.utils.text import slugify

LEGACY_CHOICE_TO_ROOT = {
    "electronics": "electronics",
    "fashion": "fashion",
    "home": "home-garden",
    "books": "books",
    "sports": "sports-outdoors",
    "toys": "toys-games",
    "food": "food-beverages",
    "beauty": "beauty-health",
    "other": "miscellaneous",
}

LEGACY_ROOT_NAMES = {
    "electronics": ("Électronique", "إلكترونيات", "Electronics"),
    "fashion": ("Mode & Vêtements", "ألبسة وأزياء", "Fashion & Clothing"),
    "home-garden": ("Maison & Jardin", "منزل وحديقة", "Home & Garden"),
    "books": ("Livres", "كتب", "Books"),
    "sports-outdoors": ("Sport & Plein air", "رياضة وطبيعة", "Sports & Outdoors"),
    "toys-games": ("Jouets & Jeux", "ألعاب ودمى", "Toys & Games"),
    "food-beverages": ("Alimentation", "مواد غذائية", "Food & Beverages"),
    "beauty-health": ("Beauté & Santé", "جمال وصحة", "Beauty & Health"),
    "miscellaneous": ("Divers", "متنوعة", "Miscellaneous"),
}


def link_stores_to_categories(apps, schema_editor):
    """Map each store's legacy choice value onto its root category."""
    Category = apps.get_model("catalog", "Category")
    Store = apps.get_model("stores", "Store")

    existing = set(Category.objects.filter(parent__isnull=True).values_list("slug", flat=True))
    max_tree_id = Category.objects.aggregate(maximum=models.Max("tree_id"))["maximum"] or 0
    for offset, (slug, (name_fr, name_ar, name_en)) in enumerate(
        LEGACY_ROOT_NAMES.items(), start=1
    ):
        if slug in existing:
            continue
        Category.objects.create(
            slug=slug,
            name_fr=name_fr,
            name_ar=name_ar,
            name_en=name_en,
            parent=None,
            # Leaf-shaped root: valid on its own and corrected by the
            # load_categories rebuild once real children exist.
            tree_id=max_tree_id + offset,
            lft=1,
            rght=2,
            level=0,
            order=offset,
        )

    roots = {root.slug: root for root in Category.objects.filter(parent__isnull=True)}
    for store in Store.objects.exclude(legacy_category="").iterator():
        slug = LEGACY_CHOICE_TO_ROOT.get(store.legacy_category)
        if slug and slug in roots:
            store.category = roots[slug]
            store.save(update_fields=["category"])


def unmap_stores(apps, schema_editor):
    """Reverse: restore the choice string from the root's slug."""
    Store = apps.get_model("stores", "Store")
    reverse = {slug: choice for choice, slug in LEGACY_CHOICE_TO_ROOT.items()}
    for store in Store.objects.exclude(category=None).iterator():
        store.legacy_category = reverse.get(store.category.slug, "other")
        store.save(update_fields=["legacy_category"])


class Migration(migrations.Migration):

    dependencies = [
        ("catalog", "0001_initial"),
        ("stores", "0004_remove_store_stores_store_s_9cc63e_idx_and_more"),
    ]

    operations = [
        # The index follows the renamed column down; a fresh one is added on
        # the FK below so a write never pays for two.
        migrations.RemoveIndex(model_name="store", name="stores_category_newest"),
        migrations.RenameField(model_name="store", old_name="category", new_name="legacy_category"),
        migrations.AddField(
            model_name="store",
            name="category",
            field=models.ForeignKey(
                blank=True,
                null=True,
                on_delete=django.db.models.deletion.PROTECT,
                related_name="stores",
                to="catalog.category",
            ),
        ),
        migrations.RunPython(link_stores_to_categories, unmap_stores),
        migrations.RemoveField(model_name="store", name="legacy_category"),
        migrations.AddIndex(
            model_name="store",
            index=models.Index(fields=["category", "-created_at"], name="stores_category_newest"),
        ),
    ]
